"""Self-contained report presentation; no external runtime assets."""

REPORT_WORKFLOW = r"""
// Preserve recorded results while navigating an independent investigation.
const browseHistory=[];
const filterIds=['testSearch','testStatus','testScope','testReason','testSuite','testPhase','findingSearch','findingSeverity','pathSearch','pathHealth','pathScope','pathZone','pathFamily','performanceSearch','performanceZone','performanceScope'];
const majorIssues=tests.filter(t=>['FAIL','ERROR'].includes(t.status));
const originalActivate=activateView,originalOpenTest=openTest,originalOpenPath=openPath,originalOpenFinding=openFinding,originalFindingTests=showFindingTests,originalPathTests=showPathTests;
const viewNames={tests:'Tests',findings:'Findings',overview:'Run summary',performance:'Performance',run:'Run details',paths:'Technical paths'};
function captureBrowse(){return{view:activeView,finding:focusedFinding,path:focusedPath,test:focusedTest,filters:Object.fromEntries(filterIds.map(id=>[id,document.getElementById(id)?.value||''])),openSuites:[...document.querySelectorAll('.suite-disclosure[open]')].map(el=>el.querySelector('h2')?.textContent),openGroups:[...document.querySelectorAll('.named-test[open]')].map(el=>[el.closest('.suite-block')?.querySelector('h2')?.textContent,el.querySelector('strong')?.textContent])};}
function rememberBrowse(){browseHistory.push(captureBrowse());}
function renderReturn(){const node=document.getElementById('modernReturn');if(!node)return;const last=browseHistory.at(-1),issueIndex=majorIssues.findIndex(t=>String(t.sequence)===String(focusedTest));node.classList.toggle('hidden',!last);node.innerHTML=last?`<div><button class="button" data-browse-back>← Back to ${esc(viewNames[last.view])}</button> <small>Previous filters and expanded tests retained</small></div>${focusedTest?`<div class="action-row">${issueIndex>=0?`<small>Issue ${issueIndex+1} of ${majorIssues.length}</small><button class="button" data-issue-next="${(issueIndex+1)%majorIssues.length}">Next failed check →</button>`:''}</div>`:''}`:'';}
activateView=function(view,options={}){originalActivate(view,{...options,scroll:false});renderReturn();};
openTest=function(sequence){rememberBrowse();originalOpenTest(sequence);renderReturn();};
openPath=function(id){rememberBrowse();originalOpenPath(id);renderReturn();};
openFinding=function(id){rememberBrowse();originalOpenFinding(id);renderReturn();};
showFindingTests=function(id){rememberBrowse();originalFindingTests(id);renderReturn();};
showPathTests=function(id){rememberBrowse();originalPathTests(id);renderReturn();};
function goBack(){const saved=browseHistory.pop();if(!saved)return;Object.entries(saved.filters).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.value=value;});focusedFinding=saved.finding;focusedPath=saved.path;focusedTest=saved.test;activateView(saved.view);document.querySelectorAll('.suite-disclosure').forEach(el=>{if(saved.openSuites.includes(el.querySelector('h2')?.textContent))el.open=true;});document.querySelectorAll('.named-test').forEach(el=>{const suite=el.closest('.suite-block')?.querySelector('h2')?.textContent,name=el.querySelector('strong')?.textContent;if(saved.openGroups.some(([s,n])=>s===suite&&n===name)){el.open=true;loadNamedGroup(el);}});renderReturn();}
renderTestRunSummary=function(){const c=outcomeCounts(tests),blocked=(c.BLOCKED_BY_SETUP_ERROR||0)+(c.BLOCKED_BY_PREREQUISITE||0),duration=(Date.parse(D.run.finished_at)-Date.parse(D.run.started_at))/1000;const presets=[['all','All checks',tests.length],['FAIL','Failed',c.FAIL||0],['ERROR','Execution errors',c.ERROR||0],['blocked','Blocked',blocked],['UNVERIFIED','Inconclusive',c.UNVERIFIED||0]];const active=document.getElementById('testStatus').value;document.getElementById('testRunSummary').innerHTML=`<div class="modern-run-strip"><div><strong>${tests.length.toLocaleString()} saved tests · ${suites.length} test suites</strong><p>${(environment.zones||[]).map(esc).join(' · ')} · ${(environment.networks||[]).map(n=>esc(n.name||n.label)).filter(Boolean).join(', ')||'Networks not recorded'} · ${esc(Number.isFinite(duration)?humanDuration(duration):'Duration not recorded')}</p></div><div>${statusBadge(D.run.final_status)} <span class="muted small">${c.PASS||0} passed · ${c.NOT_APPLICABLE||0} not applicable</span></div></div><div class="modern-presets">${presets.map(([v,l,n])=>`<button class="button" data-test-preset="${v}" aria-pressed="${v==='blocked'?document.getElementById('testReason').value==='prerequisite-blocked':active===v&&document.getElementById('testReason').value==='all'}">${l}<b>${n.toLocaleString()}</b></button>`).join('')}</div><details><summary>Requested host pairs and recorded traffic hosts</summary><div>${placementTable()}</div></details>`;};
const originalExecutionTable=executionTable;
executionTable=function(rows){return originalExecutionTable(rows).replace(/>(T\d+)<\/button>/g,'>Inspect $1 →</button>');};
function blockingLinks(test){return (test.blocking_checks||[]).map(root=>`<button class="button" data-open-test="${esc(root.sequence)}">View ${esc(root.reference)}: ${esc(root.title)} →</button>`).join('');}
function blockingContext(test){if(!test.status.startsWith('BLOCKED'))return '';const roots=test.blocking_checks||[];return `<div class="manual-notice blocking-context"><strong>Why this check could not run</strong><p>${esc(test.blocked_reason||test.message||'A required step did not complete.')}</p>${roots.map(root=>`<p>${esc(root.reason)}</p>`).join('')}<div class="action-row">${blockingLinks(test)}</div></div>`;}
function blockedRunSummary(){const blocked=tests.filter(t=>t.status.startsWith('BLOCKED')),roots=new Map();for(const test of blocked)for(const root of test.blocking_checks||[]){if(!roots.has(root.result_id))roots.set(root.result_id,{...root,count:0});roots.get(root.result_id).count++;}if(!blocked.length)return '';return `<div class="manual-notice blocked-summary"><strong>${blocked.length} checks could not run</strong><p>These dependent checks were not executed. ${roots.size?'Recorded blocking prerequisites:':'Open a blocked check for its recorded reason.'}</p>${[...roots.values()].map(root=>`<p><strong>${root.count} dependent checks:</strong> ${esc(root.reason)}</p><button class="button" data-open-test="${esc(root.sequence)}">View ${esc(root.reference)}: ${esc(root.title)} →</button>`).join('')}</div>`;}
const summaryBeforeBlockers=renderTestRunSummary;
renderTestRunSummary=function(){summaryBeforeBlockers();document.getElementById('testRunSummary').innerHTML+=blockedRunSummary();};
namedTestGroups=function(rows,showEvidence=false,view='tests'){
 for(const key of namedGroupRows.keys())if(key.startsWith(view+':'))namedGroupRows.delete(key);
 const groups=new Map();rows.forEach(test=>{const name=test.test_name||test.title,key=JSON.stringify([test.suite,name]);if(!groups.has(key))groups.set(key,{suite:test.suite,name,rows:[]});groups.get(key).rows.push(test);});
 const bySuite=new Map();groups.forEach(group=>{if(!bySuite.has(group.suite))bySuite.set(group.suite,[]);bySuite.get(group.suite).push(group);});
 const unfold=showEvidence||groups.size<15||bySuite.size===1;
 return [...bySuite].map(([suite,items])=>{const executions=items.flatMap(item=>item.rows);return '<details class="suite-block suite-disclosure"'+(unfold?' open':'')+'><summary class="suite-header"><span class="suite-arrow" aria-hidden="true">›</span><div><h2>'+esc(suite)+'</h2><small>'+items.length+' test types · '+executions.length+' executions</small></div><div class="suite-outcomes">'+outcomeChips(executions)+'</div></summary>'+items.map(group=>{const key=view+':'+(++namedGroupSequence);namedGroupRows.set(key,group.rows);return '<details class="named-test" data-named-group="'+key+'"'+(showEvidence?' open data-group-loaded="true"':'')+'><summary class="named-test-heading"><span><strong>'+esc(group.name)+'</strong><small>'+group.rows.length+' executions</small></span><span class="group-outcomes">'+outcomeChips(group.rows)+'</span></summary><div class="group-executions">'+(showEvidence?group.rows.map(testCard).join(''):'')+'</div></details>';}).join('')+'</details>';}).join('');
};
testCard=function(test){
 const path=pathById.get(test.path_id),story=test.operator_explanation||{},c=test.human_context||{},ev=test.evidence||{},hasOutput=Boolean(ev.stdout||ev.stderr),failed=['FAIL','ERROR'].includes(test.status),captured=[...(story.location||[]),...(story.facts||[])],limits=story.limitations||[],needsFollowup=Boolean(story.attention||test.status!=='PASS'||story.interruption_observations?.length);
 return `<article class="modern-inspection" id="test-${test.sequence}" data-test-sequence="${test.sequence}"><header><div><span class="eyebrow">${esc(test.reference)} / ${esc(test.suite)}</span><h2>${esc(test.test_name||c.test||test.title)}</h2><p class="test-route">${esc(c.path||'Recorded network path')}</p><p class="test-addresses">${esc(addressFlow(test)||test.address_summary||endpointPairForTest(test))}</p><div class="test-meta">${[c.protocol,c.family||test.family].filter(Boolean).map(value=>badge(value)).join('')}${c.timing?badge(c.timing):''}${c.action?badge(c.action):''}</div></div>${resultBadges(test)}</header>${humanContextHtml(test)}${interruptionObservationHtml(story)}<div class="modern-result-pair"><div><span>Expected result</span><p>${esc(test.expected||'The expected result was not recorded.')}</p></div><div><span>Actual result</span><p>${esc(test.observed||test.message||'The actual result was not recorded.')}</p></div></div><section class="result-meaning"><h3>Why this ${test.status==='PASS'?'passed':test.status==='FAIL'?'failed':'has this result'}</h3><p>${esc(outcomeReason(test)||'The report has no recorded interpretation for this result.')}</p>${limits.length?`<ul>${limits.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>`:''}</section><div class="modern-diagnostic"><div><h3>Command and output</h3>${ev.command?`<details><summary>Recorded command</summary><pre>${esc(ev.command)}</pre></details>`:''}${hasOutput?`${ev.stdout?`<details><summary>Standard output</summary><pre>${esc(ev.stdout)}</pre></details>`:''}${ev.stderr?`<details><summary>Standard error</summary><pre>${esc(ev.stderr)}</pre></details>`:''}`:`<p class="muted">No command output is embedded for this result.</p>`}<div class="action-row"><button class="button" data-copy-test="${test.sequence}">Copy result summary</button>${path?`<button class="button" data-open-path="${esc(path.path_id)}">View network path</button>`:''}</div></div>${needsFollowup?`<div><h3>${failed?'Diagnosis and next check':'Observation and follow-up'}</h3><div class="diagnostic-note"><h4>Next check</h4><p>${esc(story.next_check||'Review the saved measurements and limits for this result.')}</p></div></div>`:''}</div><details><summary>Additional diagnostic facts (${captured.length})</summary><div class="details-inner"><dl class="technical"><div><dt>Requested host pair</dt><dd>${esc(test.host_scope?.requested_pair||'No explicit host pair recorded')}</dd></div>${captured.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(f.value)}</dd></div>`).join('')}</dl></div></details><details><summary>Saved measurements, commands and supporting samples</summary><div class="details-inner">${sampleEvidence(test)}${evidenceBlock(test)}</div></details><details><summary>Run the tests again</summary><div class="details-inner">${rerunHtml(test)}</div></details><details><summary>Test ID and timing</summary><div class="details-inner"><pre>${esc(test.result_id)}
Started: ${esc(test.started_at||'Unavailable')}
Duration: ${esc(test.duration_ms||0)} ms</pre></div></details></article>`;
};
document.body.addEventListener('click',event=>{const back=event.target.closest('[data-browse-back]');if(back){goBack();return;}const next=event.target.closest('[data-issue-next]');if(next){const test=majorIssues[Number(next.dataset.issueNext)];if(test){originalOpenTest(test.sequence);renderReturn();}return;}const preset=event.target.closest('[data-test-preset]');if(preset){focusedTest=null;focusedPath=null;focusedFinding=null;document.getElementById('testReason').value=preset.dataset.testPreset==='blocked'?'prerequisite-blocked':'all';document.getElementById('testStatus').value=preset.dataset.testPreset==='blocked'?'all':preset.dataset.testPreset;renderTests();renderContext();return;}});
document.body.addEventListener('click',event=>{if(event.target.closest('[data-view-link]')){browseHistory.length=0;renderReturn();}},true);

"""
